#include <cstdio>
#include <iostream>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t child = fork();

    if (child == -1) {
        std::perror("fork");
        return 1;
    }

    if (child == 0) {
        // ① 输出子进程自己的 PID，以及它的 PPID
        std::cout << "child PID:" <<getpid() << "PPID:" << getppid() << "\n";
        return 0;
    }

    pid_t reaped = waitpid(child, nullptr, 0);
    if (reaped == -1) {
        std::perror("waitpid");
        return 1;
    }

    // ② 输出父进程自己的 PID，以及变量 child 的值
    std::cout << "parent PID:" << getpid() << " child:" << child << "\n";
    // ③ 输出变量 reaped 的值
    std::cout << "reaped:" << reaped << "\n";
    return 0;
}
